begin;
create or replace function reservations_private.get_public_registration_family_request(p_device_id uuid,p_request_id uuid)returns jsonb language plpgsql stable security definer set search_path='' as $$
declare b jsonb;r reservations.public_registration_requests%rowtype;items jsonb;begin b:=reservations_private.get_public_registration_request(p_device_id,p_request_id);select * into r from reservations.public_registration_requests where id=p_request_id;select coalesce(jsonb_agg(jsonb_build_object('member',jsonb_strip_nulls(jsonb_build_object('memberKey',m.member_key,'ordinal',m.ordinal,'role',m.role,'guardianMemberKey',m.guardian_member_key,'bookingTypeId',m.booking_type_id,'bookingTypeName',bt.name,'currentPrice',bt.price,'fullName',m.full_name,'phone',m.phone,'gender',m.gender,'dateOfBirth',m.date_of_birth,'church',m.church,'governorate',m.governorate,'cityOrVillage',m.city_or_village,'serviceSector',m.service_sector,'serviceSectorOther',m.service_sector_other,'notes',m.notes,'resolvedPersonId',m.resolved_person_id,'bookingId',m.booking_id)),'identityCandidates',platform_private.reservations_person_identity_candidates(m.full_name,m.phone,10))order by m.ordinal),'[]'::jsonb)into items from reservations.public_registration_request_members m left join reservations.booking_types bt on bt.id=m.booking_type_id and bt.event_id=r.event_id where m.request_id=r.id;return b||jsonb_build_object('members',items);end $$;
revoke all on function reservations_private.get_public_registration_family_request(uuid,uuid)from public,anon,authenticated,service_role;

create or replace function reservations_private.decide_public_registration_family_request(p_device_id uuid,p_operation_id uuid,p_request_id uuid,p_expected_revision bigint,p_decision text,p_resolutions jsonb,p_reason text)returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare r reservations.public_registration_requests%rowtype;e reservations.events%rowtype;ctx jsonb;actor uuid;pm reservations.public_registration_request_members%rowtype;m reservations.public_registration_request_members%rowtype;res jsonb;choice text;pid uuid;br jsonb;bid uuid;age int;args jsonb;gp uuid;gpart uuid;cpart uuid;result jsonb;
begin select * into r from reservations.public_registration_requests where id=p_request_id for update;if not found then raise exception 'PUBLIC_REGISTRATION_REQUEST_NOT_FOUND' using errcode='P0002';end if;ctx:=reservations_private.resolve_event_scope(p_device_id,r.event_id,'reservations.booking.create');actor:=(ctx->>'actorUserId')::uuid;
if p_decision in('reject','waitlist')then return reservations_private.decide_public_registration_request(p_device_id,p_operation_id,p_request_id,p_expected_revision,p_decision,null,p_reason);end if;if p_decision<>'approve' or jsonb_typeof(p_resolutions)<>'object' then raise exception 'PUBLIC_REGISTRATION_FAMILY_DECISION_INVALID' using errcode='22023';end if;
select * into e from reservations.events where id=r.event_id and scope_partition_id=(ctx->>'scopePartitionId')::uuid;select * into pm from reservations.public_registration_request_members where request_id=r.id and ordinal=0;res:=p_resolutions->pm.member_key::text;choice:=res->>'decision';pid:=nullif(res->>'personId','')::uuid;if choice not in('existing','new')or(choice='existing' and pid is null)or(choice='new' and pid is not null)then raise exception 'PUBLIC_REGISTRATION_MEMBER_RESOLUTION_REQUIRED' using errcode='22023';end if;
result:=reservations_private.decide_public_registration_request(p_device_id,p_operation_id,p_request_id,p_expected_revision,case when choice='existing' then 'approve_existing' else 'approve_new' end,pid,p_reason);select resolved_person_id,booking_id into pid,bid from reservations.public_registration_requests where id=r.id;update reservations.public_registration_request_members set resolved_person_id=pid,booking_id=bid where request_id=r.id and ordinal=0;
for m in select * from reservations.public_registration_request_members where request_id=r.id and ordinal>0 order by ordinal for update loop if m.resolved_person_id is not null then continue;end if;res:=p_resolutions->m.member_key::text;choice:=res->>'decision';pid:=nullif(res->>'personId','')::uuid;if choice not in('existing','new')or(choice='existing' and pid is null)or(choice='new' and pid is not null)then raise exception 'PUBLIC_REGISTRATION_MEMBER_RESOLUTION_REQUIRED' using errcode='22023';end if;if choice='existing' and not exists(select 1 from jsonb_array_elements(platform_private.reservations_person_identity_candidates(m.full_name,m.phone,10))c where c->>'personId'=pid::text)then raise exception 'PUBLIC_REGISTRATION_PERSON_CANDIDATE_STALE' using errcode='40001';end if;
if m.role<>'child_dependent' then if m.date_of_birth is null or m.date_of_birth>e.start_date then raise exception 'PUBLIC_REGISTRATION_DATE_OF_BIRTH_INVALID' using errcode='22023';end if;age:=extract(year from pg_catalog.age(e.start_date,m.date_of_birth))::int;args:=jsonb_strip_nulls(jsonb_build_object('p_operation_id',extensions.gen_random_uuid(),'p_event_id',r.event_id,'p_booking_type_id',m.booking_type_id,'p_full_name',m.full_name,'p_phone',m.phone,'p_age',age,'p_church',m.church,'p_governorate',m.governorate,'p_city_or_village',m.city_or_village,'p_service_sector',m.service_sector,'p_service_sector_other',m.service_sector_other,'p_notes',m.notes,'p_gender',m.gender,'p_date_of_birth',m.date_of_birth,'p_person_id',case when choice='existing' then pid else null end));br:=reservations.mutate(p_device_id,'create_booking',args);if choice='new' and coalesce((br->>'identityResolutionRequired')::boolean,false)then br:=reservations.mutate(p_device_id,'create_booking',args||jsonb_build_object('p_identity_resolution_token',br->>'identityResolutionToken','p_identity_resolution_decision','different'));end if;bid:=nullif(br->>'bookingId','')::uuid;if bid is null then raise exception 'PUBLIC_REGISTRATION_IDENTITY_RESOLUTION_STALE' using errcode='40001';end if;select p.person_id into pid from reservations.bookings b join reservations.participants p on p.id=b.participant_id and p.scope_partition_id=b.scope_partition_id where b.id=bid;update reservations.public_registration_request_members set resolved_person_id=pid,booking_id=bid where id=m.id;
else if choice='new' then insert into platform.people(full_name,phone,gender,date_of_birth,church,governorate,city_or_village,service_sector,service_sector_other,created_by,updated_by)values(m.full_name,nullif(m.phone,''),'child',m.date_of_birth,nullif(m.church,''),nullif(m.governorate,''),nullif(m.city_or_village,''),nullif(m.service_sector,''),m.service_sector_other,actor,actor)returning id into pid;end if;select gm.resolved_person_id into gp from reservations.public_registration_request_members gm where gm.request_id=r.id and gm.member_key=m.guardian_member_key;if gp is null then raise exception 'PUBLIC_REGISTRATION_GUARDIAN_INVALID' using errcode='22023';end if;select cp.id into gpart from public.conference_participations cp where cp.conference_id=e.conference_id and cp.person_id=gp and cp.status='active';if gpart is null then insert into public.conference_participations(conference_id,person_id,status,created_by,updated_by)values(e.conference_id,gp,'active',actor,actor)returning id into gpart;end if;select cp.id into cpart from public.conference_participations cp where cp.conference_id=e.conference_id and cp.person_id=pid;if cpart is null then insert into public.conference_participations(conference_id,person_id,guardian_participation_id,status,created_by,updated_by)values(e.conference_id,pid,gpart,'active',actor,actor)returning id into cpart;elsif exists(select 1 from public.conference_participations where id=cpart and guardian_participation_id is distinct from gpart)then raise exception 'PUBLIC_REGISTRATION_CHILD_GUARDIAN_CONFLICT' using errcode='40001';end if;update reservations.public_registration_request_members set resolved_person_id=pid where id=m.id;end if;end loop;
result:=result||jsonb_build_object('members',reservations_private.public_registration_members_json(r.id));update reservations.public_registration_requests set decision_result=result where id=r.id;return result;end $$;
revoke all on function reservations_private.decide_public_registration_family_request(uuid,uuid,uuid,bigint,text,jsonb,text)from public,anon,authenticated,service_role;

do $route$ declare o oid:='platform.execute_device_operation(uuid,uuid,bytea,text,text,jsonb)'::regprocedure;d text;n text;a text:=E'    when \'decide_public_registration_request\' then';i text:=E'    when \'decide_public_registration_family_request\' then\n      perform platform_private.require_exact_jsonb_keys(p_args,array[\'p_operation_id\',\'p_request_id\',\'p_expected_revision\',\'p_decision\'],array[\'p_resolutions\',\'p_reason\']);\n      return reservations_private.decide_public_registration_family_request(v_session.device_id,(p_args->>\'p_operation_id\')::uuid,(p_args->>\'p_request_id\')::uuid,(p_args->>\'p_expected_revision\')::bigint,p_args->>\'p_decision\',coalesce(p_args->\'p_resolutions\',\'{}\'::jsonb),p_args->>\'p_reason\');\n    when \'decide_public_registration_request\' then';begin select pg_get_functiondef(o)into d;if position('decide_public_registration_family_request' in d)>0 then raise exception 'PUBLIC_REGISTRATION_FAMILY_DECISION_DISPATCH_ALREADY_PRESENT';end if;if position(a in d)=0 then raise exception 'PUBLIC_REGISTRATION_FAMILY_DECISION_DISPATCH_ANCHOR_MISMATCH';end if;n:=replace(d,a,i);execute n;end $route$;
do $read$ declare o oid:='platform.execute_device_operation(uuid,uuid,bytea,text,text,jsonb)'::regprocedure;d text;n text;a text:=E'return reservations_private.get_public_registration_request(v_session.device_id,(p_args->>\'p_request_id\')::uuid);';i text:=E'return reservations_private.get_public_registration_family_request(v_session.device_id,(p_args->>\'p_request_id\')::uuid);';begin select pg_get_functiondef(o)into d;if position(a in d)=0 then raise exception 'PUBLIC_REGISTRATION_FAMILY_GET_ANCHOR_MISMATCH';end if;n:=replace(d,a,i);execute n;end $read$;
commit;